void av_glDrawBuffers(::av::ClientTransport& av_t, GLsizei n, const GLenum* bufs) {
    AV_SCOPE("av_glDrawBuffers");
    const uint64_t av_blob_sizes[] = {bufs != nullptr && static_cast<size_t>((static_cast<size_t>(n) * sizeof(GLenum))) >= ::av::glproto::kPixelBlobFloor ? static_cast<uint64_t>(static_cast<size_t>((static_cast<size_t>(n) * sizeof(GLenum)))) : 0u};
    ::av::WireWriter av_b = (av_blob_sizes[0]) != 0u ? av_t.request_writer_with_room(av_blob_sizes, 1u) : av_t.request_writer();
    av_b.write_varint(static_cast<uint64_t>(n));
    size_t bufs_want = 0;
    if (bufs != nullptr) bufs_want = (static_cast<size_t>(n) * sizeof(GLenum));
    ::av::ClientBlobLease bufs_lease{};
    bool bufs_via_blob = false;
    if (bufs != nullptr &&
        bufs_want >= ::av::glproto::kPixelBlobFloor) {
        auto& av_blobs = av_t.blobs();
        if (av_blobs.ready()) {
            bufs_lease = av_blobs.take(bufs_want);
            if (bufs_lease.taken()) {
                __builtin_memcpy(bufs_lease.data(), bufs, bufs_want);
                bufs_via_blob = true;
            }
        }
        if (!bufs_via_blob) av_t.note(::av::ChannelCounter::inline_bulk, 1u);
    }
    av_b.write_pod<uint8_t>(bufs == nullptr ? 0 : (bufs_via_blob ? 3 : 1));
    if (bufs_via_blob) {
        av_b.write_varint(static_cast<uint64_t>(bufs_want));
        av_b.write_varint(static_cast<uint64_t>(bufs_lease.offset()));
    } else if (bufs != nullptr) {
        av_b.write_varint(static_cast<uint64_t>(bufs_want));
        if (bufs_want != 0) av_b.write(bufs, bufs_want);
    }
    if (av_b.status() != ::av::Status::ok) {
        ::av::icd::payload_dropped("gl", "glDrawBuffers",
                                       av_b.offset());
        if (bufs_via_blob) {
            av_t.blobs()
                .give_back(bufs_lease);
        }
        av_t.end_call();
        return;
    }
    (void)av_t.send_async(kCmd_glDrawBuffers, av_b);
}

